import{_ as l,C as a,o as n,c as s,j as e,a as d,E as o,a5 as i}from"./chunks/framework.Dep_XxFZ.js";const P=JSON.parse('{"title":"分栏","description":"","frontmatter":{},"headers":[],"relativePath":"components/splitter.md","filePath":"components/splitter.md","lastUpdated":1787173379000}'),h={name:"components/splitter.md"},p={id:"分栏",tabindex:"-1"};function b(g,t,u,x,m,f){const c=a("Badge"),r=a("XhDemo");return n(),s("div",null,[e("h1",p,[t[0]||(t[0]=d("分栏 ",-1)),o(c,{type:"info",text:"splitter"}),t[1]||(t[1]=d()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#分栏","aria-label":'Permalink to "分栏 <Badge type="info" text="splitter" />"'},"​",-1))]),t[3]||(t[3]=i('<p>把一块区域拆成几片可拖动的面板，边界由用户自己分配。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>代码编辑器、文件管理器、带预览的编辑界面这类&quot;两边都重要、比例因人而异&quot;的布局。</li><li>用户调好的比例需要记下来：<code>onSizesChangeEnd</code> 就是为此留的。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>比例是固定的：用<a href="./grid">栅格</a>或<a href="./flex">弹性布局</a>。</li><li>侧栏只有展开与折叠两态：用<a href="./layout">布局</a>的折叠侧栏。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><code>panels</code> 数组的长度决定面板块数，每条分隔条调的是它前面那一块。</li><li>两个回调分工明确：<code>onSizesChange</code> 拖动途中连着发，<code>onSizesChangeEnd</code> 松手才发一次，存布局用后者。</li><li>方向键按 <code>step</code> 推、Shift 加方向键按 <code>largeStep</code> 推；<code>collapsible</code> 的面板在分隔条上按 Enter 折叠。</li><li>面板里再放一套分栏即可拆出第二根轴，里外两层各管各的尺寸。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>panels 数组的长度决定面板块数，每条分隔条调的是它前面那一块</p>',10)),o(r,{src:"splitter/01-basic"}),t[4]||(t[4]=e("h3",{id:"受控",tabindex:"-1"},[d("受控 "),e("a",{class:"header-anchor",href:"#受控","aria-label":'Permalink to "受控"'},"​")],-1)),t[5]||(t[5]=e("p",null,"传了 sizes 就由宿主说了算；sizes-change 拖动途中连着发，sizes-change-end 松手才发一次",-1)),o(r,{src:"splitter/02-controlled"}),t[6]||(t[6]=e("h3",{id:"竖排与折叠",tabindex:"-1"},[d("竖排与折叠 "),e("a",{class:"header-anchor",href:"#竖排与折叠","aria-label":'Permalink to "竖排与折叠"'},"​")],-1)),t[7]||(t[7]=e("p",null,"orientation 换轴后方向键跟着换，collapsible 的面板在它的分隔条上按 Enter 折叠",-1)),o(r,{src:"splitter/03-vertical-collapsible"}),t[8]||(t[8]=e("h3",{id:"禁用",tabindex:"-1"},[d("禁用 "),e("a",{class:"header-anchor",href:"#禁用","aria-label":'Permalink to "禁用"'},"​")],-1)),t[9]||(t[9]=e("p",null,"disabled 后拖不动也推不动，分隔条整个退出 Tab 序列，方向键放行给页面",-1)),o(r,{src:"splitter/04-disabled"}),t[10]||(t[10]=e("h3",{id:"嵌套",tabindex:"-1"},[d("嵌套 "),e("a",{class:"header-anchor",href:"#嵌套","aria-label":'Permalink to "嵌套"'},"​")],-1)),t[11]||(t[11]=e("p",null,"面板里再放一套分栏即可拆出第二根轴，里外两层各管各的尺寸，互不干涉",-1)),o(r,{src:"splitter/05-nested"}),t[12]||(t[12]=e("h3",{id:"分隔条里放内容",tabindex:"-1"},[d("分隔条里放内容 "),e("a",{class:"header-anchor",href:"#分隔条里放内容","aria-label":'Permalink to "分隔条里放内容"'},"​")],-1)),t[13]||(t[13]=e("p",null,"分隔条内可以再摆一个把手，粗细由 --xh-splitter-trigger-thickness 让出位置",-1)),o(r,{src:"splitter/06-trigger-content"}),t[14]||(t[14]=i('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-splitter&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhSplitterPanel</code> <code>XhSplitterResizeTrigger</code> <code>XhSplitterRoot</code></td></tr><tr><td>组合式函数</td><td><code>useSplitter</code></td></tr><tr><td>状态机</td><td><code>splitterMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/splitter.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;splitter&quot;</code>：<strong><code>root</code></strong> · <strong><code>panel</code></strong> · <strong><code>resize-trigger</code></strong></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>sizes</code></td><td><code>number[]</code></td><td></td><td>每块面板的百分比。给定即受控：内部不再自改，只发 onSizesChange。</td></tr><tr><td><code>defaultSizes</code></td><td><code>number[]</code></td><td></td><td>非受控初值；不给就按面板数等分。</td></tr><tr><td><code>panels</code></td><td><code>SplitterPanelProps[]</code></td><td></td><td>逐块的约束；数组长度同时决定面板块数。</td></tr><tr><td><code>orientation</code></td><td><code>Orientation</code></td><td></td><td>面板的排布轴，默认 horizontal（并排，拖左右）；vertical 是上下堆叠，拖上下。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，默认 ltr；只对调水平排布下的左右两键与指针位移的正负。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>禁用：分隔条退出 Tab 序列、拖不动也推不动。</td></tr><tr><td><code>step</code></td><td><code>number</code></td><td></td><td>方向键的步长（百分比），默认 1。</td></tr><tr><td><code>largeStep</code></td><td><code>number</code></td><td></td><td>Shift + 方向键的步长（百分比），默认 10。</td></tr><tr><td><code>onSizesChange</code></td><td><code>(details: SplitterSizesChangeDetails) =&gt; void</code></td><td></td><td>每次尺寸变化都发；拖动过程中会连续发很多次。</td></tr><tr><td><code>onSizesChangeEnd</code></td><td><code>(details: SplitterSizesChangeEndDetails) =&gt; void</code></td><td></td><td>只在一次操作结束时发一次，适合拿来存布局。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>sizes-change</code></td><td><code>SplitterSizesChangeDetails</code></td><td>布局变化（拖动途中会连发）；detail 为 <code>{ sizes: number[] }</code></td></tr><tr><td><code>sizes-change-end</code></td><td><code>SplitterSizesChangeEndDetails</code></td><td>一次拖拽收尾发一次；detail 为 <code>{ sizes: number[], index: number }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhSplitterRoot</code></td><td><code>default</code></td><td><code>SplitterRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code> · <code>dragging</code></p><p><strong>事件</strong>：<code>SIZES.SET</code> · <code>BOUNDARY.STEP</code> · <code>BOUNDARY.TO_MIN</code> · <code>BOUNDARY.TO_MAX</code> · <code>BOUNDARY.SET</code> · <code>BOUNDARY.FOCUS</code> · <code>PANEL.COLLAPSE</code> · <code>PANEL.EXPAND</code> · <code>DRAG.START</code> · <code>DRAG.MOVE</code> · <code>DRAG.END</code></p><p><strong>判据</strong>：<code>canResize</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useSplitter</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>sizes</code></td><td><code>number[]</code></td><td></td></tr><tr><td><code>panels</code></td><td><code>SplitterPanelState[]</code></td><td></td></tr><tr><td><code>dragging</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>setSizes</code></td><td><code>(next: number[]) =&gt; void</code></td><td>整份赋值：逐块夹进约束、总和归位到 100 之后才落地。</td></tr><tr><td><code>setPanelSize</code></td><td><code>(index: number, next: number) =&gt; void</code></td><td>把第 index 块调到 next，缺的那部分从它后面的面板里取。 最后一块没有属于自己的分隔条，它的尺寸是其余面板的余数，调不动。</td></tr><tr><td><code>collapsePanel</code></td><td><code>(index: number) =&gt; void</code></td><td></td></tr><tr><td><code>expandPanel</code></td><td><code>(index: number) =&gt; void</code></td><td></td></tr><tr><td><code>togglePanel</code></td><td><code>(index: number) =&gt; void</code></td><td>折叠着就展开、展开着就折叠；不可折叠的面板上是空操作。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getPanelProps</code></td><td><code>(index: number) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getResizeTriggerProps</code></td><td><code>(index: number) =&gt; T[&#39;element&#39;]</code></td><td>第 index 条分隔条坐在第 index 与第 index+1 块面板之间，调整的是前一块。</td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/windowsplitter/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>ArrowRight</code> / <code>ArrowDown</code></td><td>focus in resize-trigger, not disabled</td><td>把这条分隔条前面那块面板按 step（默认 1%）撑大；水平排布认左右键、竖直排布认上下键，另一条轴上的方向键原样放行</td></tr><tr><td><code>ArrowLeft</code> / <code>ArrowUp</code></td><td>focus in resize-trigger, not disabled</td><td>按 step 压小，同上的轴向规则；rtl 下左右两键对调，语义恒是&quot;撑大 / 压小前一块&quot;</td></tr><tr><td><code>Shift+ArrowRight</code> / <code>Shift+ArrowDown</code></td><td>focus in resize-trigger, not disabled</td><td>按 largeStep（默认 10%）撑大</td></tr><tr><td><code>Shift+ArrowLeft</code> / <code>Shift+ArrowUp</code></td><td>focus in resize-trigger, not disabled</td><td>按 largeStep 压小</td></tr><tr><td><code>Home</code></td><td>focus in resize-trigger, not disabled</td><td>把前一块面板收到它眼下能到的最小尺寸</td></tr><tr><td><code>End</code></td><td>focus in resize-trigger, not disabled</td><td>把前一块面板撑到它眼下能到的最大尺寸</td></tr><tr><td><code>Enter</code></td><td>focus in resize-trigger 且它调整的面板 collapsible，not disabled</td><td>折叠 / 展开该面板；展开回到折叠前的尺寸。面板不可折叠时不接这个键</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;group&#39;</td></tr><tr><td><code>resize-trigger</code></td><td><code>aria-controls</code></td><td><code>panel</code> 部件的 id</td></tr><tr><td><code>resize-trigger</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>resize-trigger</code></td><td><code>aria-orientation</code></td><td>&#39;horizontal&#39; | &#39;vertical&#39;</td></tr><tr><td><code>resize-trigger</code></td><td><code>aria-valuemax</code></td><td>String(panel.max)</td></tr><tr><td><code>resize-trigger</code></td><td><code>aria-valuemin</code></td><td>String(panel.min)</td></tr><tr><td><code>resize-trigger</code></td><td><code>aria-valuenow</code></td><td>String(panel.size)</td></tr><tr><td><code>resize-trigger</code></td><td><code>role</code></td><td>&#39;separator&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/splitter.css</code> 按部件选择：<code>[data-scope=&quot;splitter&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>panel</code></td><td><code>data-collapsed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>panel</code></td><td><code>data-index</code></td><td>String(panel.index)</td></tr><tr><td><code>resize-trigger</code></td><td><code>data-dragging</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>resize-trigger</code></td><td><code>data-index</code></td><td>String(boundary)</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-splitter-radius</code> · <code>--xh-splitter-trigger-bg</code> · <code>--xh-splitter-trigger-bg-disabled</code> · <code>--xh-splitter-trigger-bg-dragging</code> · <code>--xh-splitter-trigger-bg-hover</code> · <code>--xh-splitter-trigger-thickness</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>面板里放<a href="./scroll-area">滚动区域</a>，让每一片各自滚动。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>给每块面板设最小尺寸，否则能被拖到完全看不见、也拖不回来。</li><li>存布局用 <code>onSizesChangeEnd</code>：拖动途中的每一帧都写存储会把主线程拖垮。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>拿它做固定比例的两栏布局：多出来的拖动能力只会让用户误操作。</li><li>分隔条做得只有一两个像素宽：指针命中率极低。</li></ul>',44))])}const q=l(h,[["render",b]]);export{P as __pageData,q as default};
